select 'Weekly Arena 2026-W50', 'Fresh weekly set of 10 numeric questions across Algebra, Geometry, Combinatorics and Number Theory. Each question allows three submissions. New questions every week, none repeated from earlier arenas.', '2026-12-07T00:00:00.000Z', '2026-12-14T00:00:00.000Z', 60, 'published', $WK0e51dd52a6be$[{"id":"wk-2026-w50-01-8e1d","title":"The Isosceles Trapezoid","topic":"Geometry","level":"Foundation","question":"An isosceles trapezoid has parallel sides of lengths $26$ and $16$ and each non-parallel side has length $13$. Find its area.","type":"text","correctAnswer":"252","hint":"Drop perpendiculars from the shorter base; each cuts off a right triangle with base $5$ and hypotenuse $13$.","solution":"The height is $\\sqrt{13^2-5^2}=12$, so the area is $\\tfrac12(26+16)(12)=252$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w50-02-5986","title":"Tangent and Secant","topic":"Geometry","level":"Intermediate","question":"From an external point $P$, a tangent $PT$ of length $19$ and a secant meeting the circle at $A$ and $B$ are drawn, with $PA < PB$ and $PA=1$. Find $PA + PB + PT$.","type":"text","correctAnswer":"381","hint":"Apply the power of a point: $PT^2=PA\\cdot PB$.","solution":"$PB=19^2/1=361$, so the sum is $1+361+19=381$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":3,"points":53,"difficulty":-0.28},{"id":"wk-2026-w50-03-e794","title":"Multiples of Two Numbers","topic":"Algebra","level":"Intermediate","question":"Find the sum of all positive integers not exceeding $278$ that are divisible by $5$ or by $9$ (or both).","type":"text","correctAnswer":"10940","hint":"Add the sum of multiples of each number, then subtract the multiples of their product that were counted twice.","solution":"Inclusion-exclusion over multiples of $5$, $9$ and $45$ gives $10940$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":4,"abstraction":2,"points":54,"difficulty":-0.24},{"id":"wk-2026-w50-04-b5ae","title":"A Blocked Lattice Path","topic":"Combinatorics","level":"Intermediate","question":"A path from $(0,0)$ to $(8,8)$ moves only one unit right or one unit up at each step. How many such paths avoid the point $(7,4)$?","type":"text","correctAnswer":"11220","hint":"Subtract the paths that pass through the forbidden point from the total.","solution":"$\\binom{16}{8}-\\binom{11}{7}\\binom{5}{1}=11220$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w50-05-e7d9","title":"Coprime Count","topic":"Number Theory","level":"Intermediate","question":"How many integers $n$ with $1\\le n\\le 563$ are relatively prime to $22$?","type":"text","correctAnswer":"256","hint":"Remove multiples of 2, 11 using inclusion-exclusion.","solution":"Inclusion-exclusion over the primes 2, 11 leaves $256$ integers.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w50-06-52ea","title":"Triangles From Diagonals Only","topic":"Geometry","level":"Intermediate","question":"Three vertices of a convex $24$-gon are chosen so that none of the three sides of the resulting triangle is a side of the polygon. How many such triangles are there?","type":"text","correctAnswer":"1520","hint":"Count all triangles and remove those that use at least one polygon side, by inclusion-exclusion.","solution":"The count is $\\dfrac{n(n-4)(n-5)}{6}$ with $n=24$, i.e. $1520$.","answerMode":"numeric-grid","answerDigits":4,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w50-07-aadb","title":"Powers of the Roots","topic":"Algebra","level":"Advanced","question":"Let $r$ and $s$ be the roots of $t^2 - 4t + 1 = 0$. Find the remainder when $r^{5} + s^{5}$ is divided by $1000$.","type":"text","correctAnswer":"724","hint":"Let $S_k=r^k+s^k$. Then $S_k=4S_{k-1}-1S_{k-2}$, with $S_0=2$, $S_1=4$.","solution":"Using $S_k=4S_{k-1}-1S_{k-2}$ from $S_0=2$, $S_1=4$ gives $S_{5}=724$, whose remainder modulo $1000$ is $724$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w50-08-9c94","title":"Bounded Distributions","topic":"Combinatorics","level":"Advanced","question":"How many ordered 3-tuples $(x_1,\\dots,x_3)$ of non-negative integers satisfy $x_1+\\cdots+x_3=10$ with every $x_i\\le 6$?","type":"text","correctAnswer":"36","hint":"Count unrestricted solutions by stars and bars, then use inclusion-exclusion on variables exceeding the bound.","solution":"Inclusion-exclusion (verified by dynamic programming) gives $36$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":5,"abstraction":3,"points":67,"difficulty":0.28},{"id":"wk-2026-w50-09-1317","title":"The Last Three Digits","topic":"Number Theory","level":"Advanced","question":"Find the remainder when $57^{80}$ is divided by $1000$.","type":"text","correctAnswer":"1","hint":"Work modulo $8$ and modulo $125$ separately and combine, or use the order of the unit in $(\\mathbb Z/1000)^\\times$.","solution":"Modular exponentiation gives $57^{80}\\equiv 1 \\pmod{1000}$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w50-10-de61","title":"A Floor Sum","topic":"Algebra","level":"Advanced","question":"Compute $\\displaystyle\\sum_{k=1}^{40} \\left\\lfloor \\frac{5k}{9} \\right\\rfloor$.","type":"text","correctAnswer":"438","hint":"Write $5k=9q+r$ and track how the remainder cycles with period $9$.","solution":"Evaluating each floor term and adding gives $438$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0}]$WK0e51dd52a6be$::jsonb
